-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.93.2',
  '2026-09-20',
  'Пульт ТВ: показ с телефона не сбивает просмотр, экраны не путаются',
  E'Отправили фото или ролик на телевизор — сериал встаёт на паузу, а когда показ закрыли, продолжается ровно с того же места. Музыка по галочке «Музыка на паузе» при этом не включается: пауза тут не ваша.\n\nПрисланное видео теперь можно мотать: на пульте появились «⏪ 30», «⏸» и «⏩ 30» для показа, а на приставке работают стрелки влево-вправо и OK. «✕ Убрать с экрана» на телефоне и «Назад» на пульте закрывают показ и возвращают к просмотру.\n\nИ починили выбор экрана: если один из плееров был открыт до обновления и его не перезагружали, пульт всё равно различает экраны — раньше в этом случае название фильма продолжало мелькать.',
  E'Причина мельтешения после 2.93.1: старая страница (её не перезагрузили) не подписывала свои ответы номером экрана, и фильтр пульта по «s» её пропускал. Теперь отправителя проставляет шина: tagSender() приклеивает «s» в начало JSON-объекта склейкой байтов, без разбора и пересборки (в сообщении бывает листинг папки на сотни файлов); поле страницы, если оно есть, идёт следом и побеждает.\n\nПлеер: флаг casting — пауза ради показа с телефона не считается зрительской (watchingVideo), поэтому «Музыка на паузе» молчит; castResume помнит, что видео играло, и closeCast() возвращает воспроизведение. castActions (playpause, back, fwd, stop) — стрелки, OK и команды пульта, пока показ открыт, относятся к нему; seek с пульта тоже уходит в него. В state добавлено поле cast {video, paused, time, duration} — по нему пульт показывает карточку показа с кнопками.\n\nПроверено: TestTagSender, локальный прод с «старой» приставкой без «s» (пульт получил её state подписанным), страница в браузере против локального прода — фото на экран (сериал на паузе, музыка молчит, «Назад» вернул просмотр), видео на экран (стрелки и пульт мотают на 30 с, OK — пауза, «Убрать» вернуло сериал).'
);
-- +goose StatementEnd

